      '6a0ebcf348b2405d6fc2f857', '6a0f1675fda5d1139320a5f3', '69b2c68f9198a99ed54877e2',
      '6985a828e82f24b05e40934f', '69b16925b8ca9bd3deda8b86', '69b80eb164f2635b1c987250',
      '69e5e531f4261d322a040315', '69c619e251404b2b13e58788', '69ef1098ef5c3f1b2da0f33a',
      '6a056c495c95daf7798d9e9c', '6a05d66befe5ffe5875cb633', '69e34afe9eee1df0dfe1c33f',
      '69a2df22317e68f10e9201fc', '69d49b51e49505a2d9ac738b', '69e21627317e68f10ec50d10',
      '69df5e90ae9546f2325804fb', '69da300f9c4298bb1f78c695', '6a154bab317e68f10eb24f27',
      '69f856c2373978761d65d83e', '6a0d8e81586de6828809257c', '697df4a8827f1d811cbc73f2',
      '6a087dd9ce09d49d63e9b97a', '6a14096c863bac1aecc99609', '69b140c3317e68f10e0e6bda',
      '6a0c5891993586e0dff0f879', '69c0cda0889f7bcc1b898776', '6a0560d5317e68f10e43b17f'
    ])
  QUALIFY ROW_NUMBER() OVER (
    PARTITION BY t.seller_id
    ORDER BY COALESCE(t.completed_at, t.created_at) DESC
  ) = 1
)
SELECT
  lt.seller_id,
  CONCAT(s.first_name, ' ', s.last_name)  AS seller_name,
  s.custom_domain                          AS website_url,
  lt.completed_at,
  lt.disposition,
  lt.remarks,
  lt.last_changed_by
FROM latest_tasks lt
LEFT JOIN `nushop.sellers` s
  ON s._id = lt.seller_id
ORDER BY lt.completed_at DESC NULLS LAST;
